#### Phase 3: Producer Integration

**Step 3.1: Add Schema Registry Client to Spring Boot Producer**

```xml
<!-- pom.xml -->
<dependency>
    <groupId>io.confluent</groupId>
    <artifactId>kafka-avro-serializer</artifactId>
    <version>7.5.0</version>
</dependency>
```

```java
// src/main/java/config/KafkaProducerConfig.java
@Configuration
public class KafkaProducerConfig {

    @Value("${spring.kafka.bootstrap-servers}")
    private String bootstrapServers;

    @Value("${spring.kafka.schema-registry.url}")
    private String schemaRegistryUrl;

    @Bean
    public ProducerFactory<String, ClaimSubmittedEvent> producerFactory() {
        Map<String, Object> config = new HashMap<>();
        config.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        config.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class);

        // Use Avro serializer with schema registry integration
        config.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,
            io.confluent.kafka.serializers.KafkaAvroSerializer.class);
        config.put("schema.registry.url", schemaRegistryUrl);

        // Auto-register schemas on first publish
        config.put("auto.register.schemas", true);

        // Use latest schema version
        config.put("use.latest.version", true);

        return new DefaultKafkaProducerFactory<>(config);
    }
}

// src/main/java/service/ClaimPublisher.java
@Service
public class ClaimPublisher {

    @Autowired
    private KafkaTemplate<String, ClaimSubmittedEvent> kafkaTemplate;

    public void publishClaimSubmitted(Claim claim) {
        ClaimSubmittedEvent event = ClaimSubmittedEvent.newBuilder()
            .setClaimId(claim.getId())
            .setMemberId(claim.getMemberId())
            .setSubmittedDate(Instant.now().toEpochMilli())
            .setClaimType(claim.getType())
            .setTotalAmount(claim.getTotalAmount())
            .setDiagnosisCodes(claim.getDiagnosisCodes())
            .setMetadata(buildMetadata())
            .build();

        // Schema automatically registered and ID embedded in message
        kafkaTemplate.send("claim-events", claim.getId(), event);
    }
}
```

