#### Phase 4: Consumer Integration

**Step 4.1: Add Schema Registry Client to Consumer**

```java
// src/main/java/config/KafkaConsumerConfig.java
@Configuration
public class KafkaConsumerConfig {

    @Value("${spring.kafka.schema-registry.url}")
    private String schemaRegistryUrl;

    @Bean
    public ConsumerFactory<String, ClaimSubmittedEvent> consumerFactory() {
        Map<String, Object> config = new HashMap<>();
        config.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        config.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);

        // Use Avro deserializer with schema registry
        config.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,
            io.confluent.kafka.serializers.KafkaAvroDeserializer.class);
        config.put("schema.registry.url", schemaRegistryUrl);

        // Enable specific Avro reader for type safety
        config.put("specific.avro.reader", true);

        return new DefaultKafkaConsumerFactory<>(config);
    }
}

// src/main/java/consumer/PaymentProcessor.java
@Service
public class PaymentProcessor {

    @KafkaListener(topics = "claim-events", groupId = "payment-service")
    public void processClaimSubmitted(ClaimSubmittedEvent event) {
        // Schema automatically retrieved by ID and validated
        log.info("Processing claim: {}", event.getClaimId());

        // Type-safe access to event fields
        if (event.getClaimType() == ClaimType.PHARMACY) {
            processPharmacyClaim(event);
        } else {
            processMedicalClaim(event);
        }
    }
}
```

