#### Example 3: Schema Evolution Example (Backward Compatible)

```json
// Version 1.0 - Initial schema
{
  "type": "record",
  "name": "MemberEligibilityEvent",
  "namespace": "com.healthcare.eligibility",
  "fields": [
    {"name": "memberId", "type": "string"},
    {"name": "effectiveDate", "type": "long"},
    {"name": "eligible", "type": "boolean"}
  ]
}

// Version 1.1 - Add optional field (backward compatible)
{
  "type": "record",
  "name": "MemberEligibilityEvent",
  "namespace": "com.healthcare.eligibility",
  "fields": [
    {"name": "memberId", "type": "string"},
    {"name": "effectiveDate", "type": "long"},
    {"name": "eligible", "type": "boolean"},
    {"name": "planType", "type": ["null", "string"], "default": null}  // NEW: optional with default
  ]
}

// Version 1.2 - Add another optional field
{
  "type": "record",
  "name": "MemberEligibilityEvent",
  "namespace": "com.healthcare.eligibility",
  "fields": [
    {"name": "memberId", "type": "string"},
    {"name": "effectiveDate", "type": "long"},
    {"name": "eligible", "type": "boolean"},
    {"name": "planType", "type": ["null", "string"], "default": null},
    {"name": "copayAmount", "type": ["null", "double"], "default": null}  // NEW: optional
  ]
}
```
